const bankTexts = {"en": {"label": "MIDI OUT Bank — Genie chance reset test", "short": "Six parallel MIDI tracks, with hardware-tested live recording.", "desc": "Experimental Sequence Genie fix: every Generate option clears per-step chance on the selected B-side lane; Undo restores the previous chance locks. Queued generation is cancelled if chance is edited before commit. A separate, parallel six-track MIDI OUT sequencer alongside the six audio tracks. FUNC + SETTINGS + TRACK opens B-side. Live recording: hold RECORD and press PLAY; press PLAY again while holding RECORD to switch quantized/unquantized recording. Keyboard and pad notes record into the selected MIDI lane. Unquantized timing uses 1/64-step resolution; recorded lengths use whole steps. Live recording was tested on hardware. Clearing a trig removes all its per-step settings and locks; re-adding starts at C5, velocity 100 and length 1. MIDI sequences and MIDI LFO settings remain RAM only. Audio LFO 2 saves its first five settings with the sound. All existing mod selections remain available."}, "fr": {"label": "Banque MIDI OUT — test reset chance Genie", "short": "Six pistes MIDI parallèles, live-rec testé sur matériel.", "desc": "Correction expérimentale Sequence Genie : toutes les options Generate effacent la chance de pas de la voie B choisie ; Undo restaure les locks précédents. Une édition chance avant commit annule le candidat en attente. Séquenceur MIDI OUT parallèle de six pistes, indépendant des six pistes audio. FUNC + SETTINGS + TRACK ouvre B. Live-rec : RECORD + PLAY ; PLAY avec RECORD maintenu bascule quantifié/libre. Notes clavier/pad enregistrées dans la voie MIDI choisie. Timing libre au 1/64 de pas ; durées en pas entiers. Live-rec testé sur matériel. Supprimer un trig efface ses réglages et locks ; le recréer donne C5, vélocité 100 et durée 1. Séquences et LFO MIDI en RAM seulement. Le LFO 2 audio sauve ses cinq premiers réglages avec le son. Toutes les sélections existantes restent disponibles."}};
const bankFeature = {
 "id": "midi-bank-bundle",
 "cat": "seq",
 "status": "experimental",
 "label": "MIDI OUT Bank",
 "desc": "FUNC + SETTINGS + TRACK ouvre ou ferme la face B. Les pads sélectionnent M1–M6 sur les canaux MIDI 7–12 ; FUNC + pad bascule MIDI OUT. REC actif : appuyez sur un trig pour ajouter ou retirer un pas, ou maintenez-le et tournez DATA pour choisir sa note. REC inactif : les trigs jouent le clavier selon gamme et tonalité Model-TG. SETTINGS + trig bascule le slide : la note suivante chevauche la précédente pour le legato du synthé. PAGE visite seulement les pages de la longueur de voie. FUNC + PAGE ouvre Scale Setup de style stock avec tous les réglages de voie ; DATA choisit un pas hors menu. Le pad sélectionné est allumé et les notes séquencées font pulser les pads. TEMPO, REC et LFO sont transmis aux handlers natifs ; leur comportement complet reste à vérifier sur matériel. Arrêtez la lecture avant la première ouverture après démarrage. Les séquences suivent le pattern actif en RAM et disparaissent au redémarrage. Sauvegarde, isolation des projets et routage LFO vers CC restent inachevés. Utilisez un seul projet et redémarrez avant de changer de projet. Ce test inclut le bundle Tout sélectionner compatible avec Model-TG et les moteurs Syntakt. Les commandes précédentes ont été testées sur matériel le 12 octobre 2026, puis un défaut de routage FUNC + pad a été signalé. La correction FUNC + pad MIDI a été testée sur matériel. Ce nouveau candidat rétablit la sortie FUNC + SETTINGS + TRACK et affiche M1–M6 avec une police stock compacte. Côté B, SETTINGS + PAGE ouvre Sequence Genie pour la voie MIDI sélectionnée : Generate et Undo s’appliquent immédiatement à l’arrêt, ou au prochain tour de cette voie en lecture. Undo annule une demande en attente. Une édition de la voie ou un changement de pattern annule la demande. Gamme/tonalité, plage de notes, densité, plage de vélocité, cible rythme/notes, mutation et Euclide concernent les notes MIDI. Decay et pan concernent uniquement les pistes audio. Ces ajouts restent à tester sur matériel ; sauvegarde inachevée.",
 "requires": "model-tg",
 "credit": {
  "kind": "based",
  "who": "TinyGregAudio",
  "repo": "TinyGregAudio/Model-TG"
 },
 "license": "LICENSE-Model-TG",
 "variants": [
  {
   "id": "midi-bank-bundle",
   "label": null
  }
 ]
};
for (const key of ["label", "short", "desc"]) Object.defineProperty(bankFeature, key, {
  get: () => (bankTexts[document.documentElement.lang] || bankTexts.en)[key], configurable: true
});
window.MC_TWEAKS.features.push(bankFeature);
Object.assign(window.MCFlasherApp.REF_MODS, {
 "midi-bank-bundle": {
  "w": "b7613e95a10e9c82d758c2f3d2bd6e349c85dff6156e576261086047915028bd",
  "p": "9a247b4a5659a7a9395212b66ab5ca44bf5815b0cbfc6484e28bd05371222105"
 }
});
Object.assign(window.MCFlasherApp.REF_MAINOS, {
 "6ch-usbup+model-tg-st+sample-preview-st+trig-hold+arp+tempo-max+boot-anim+multiline-browser+level-pan-values+trigless-dim+midi-live-both+syntakt-tg-sd-cp-toy-bits-swarm-macro-acid+scale-gen-st-queued+lfo-secondary+scramble-st-gen-queued+midi-bank-bundle": "0879f0d731f2ce82a6bf2b0a949c2a39a4d90e278f3279f75a2cbdf9ee27808c",
 "model-tg-st+sample-preview-st+trig-hold+arp+tempo-max+boot-anim+multiline-browser+level-pan-values+trigless-dim+midi-live-both+syntakt-tg-sd-cp-toy-bits-swarm-macro-acid+scale-gen-st-queued+lfo-secondary+scramble-st-gen-queued+midi-bank-bundle": "f52c494fa4edb92f37105e00e38fabea87c113d899bf05e976017e8a0f3d215a"
});
// Utiliser le vrai bouton Select all avant de cocher la carte.
document.addEventListener("change", event => {
  if (event.target.id === "feat-midi-bank-bundle" && event.target.checked) {
    document.getElementById("select-all").click();
  }
}, true);


// LFO2 quick assign : pas de sauvegarde expérimentale.
